//! Cloud LLM model registry, from [models.dev](https://models.dev): names,
//! context windows, prices and capabilities of the models Guidy's providers
//! offer.
//!
//! A trimmed snapshot ships with the app (`assets/llm-registry.json`,
//! regenerated by `scripts/update_llm_registry.py`). At runtime a fresher
//! copy is downloaded at most once a day into `<app data>/llm-registry.json`
//! and used instead. Both use models.dev's own schema, parsed here.
//!
//! The model picker combines the registry with the provider's live model
//! list ([`merge_models`]): the registry says what a model is, the live list
//! says what this API key can use.

use std::collections::HashMap;
use std::path::PathBuf;
use std::sync::{Arc, OnceLock};
use std::time::{Duration, SystemTime, UNIX_EPOCH};

use anyhow::{anyhow, Context, Result};
use parking_lot::{Mutex, RwLock};
use serde::{Deserialize, Serialize};

use crate::host::AppHandle;
use crate::settings::{
    CLOUDFLARE_AI_GATEWAY_PROVIDER_ID, CLOUDFLARE_WORKERS_AI_PROVIDER_ID,
    VERCEL_AI_GATEWAY_PROVIDER_ID,
};

pub const REGISTRY_URL: &str = "https://models.dev/api.json";
const CACHE_FILE: &str = "llm-registry.json";
/// How old the downloaded copy may get before it's refreshed.
const MAX_AGE: Duration = Duration::from_secs(24 * 60 * 60);
const BUNDLED: &str = include_str!("../../../../assets/llm-registry.json");

/// (Guidy provider id, models.dev provider id) for the providers models.dev
/// describes. Keep in sync with `PROVIDERS` in
/// `scripts/update_llm_registry.py`.
const PROVIDERS: [(&str, &str); 9] = [
    ("anthropic", "anthropic"),
    ("cerebras", "cerebras"),
    ("groq", "groq"),
    ("openai", "openai"),
    ("openrouter", "openrouter"),
    ("zai", "zai"),
    (VERCEL_AI_GATEWAY_PROVIDER_ID, "vercel"),
    (CLOUDFLARE_WORKERS_AI_PROVIDER_ID, "cloudflare-workers-ai"),
    (CLOUDFLARE_AI_GATEWAY_PROVIDER_ID, "cloudflare-ai-gateway"),
];

/// The models.dev provider for a Guidy provider id. Providers models.dev
/// doesn't describe (custom endpoints, Bedrock Mantle's own ids) have none.
pub fn models_dev_provider(provider_id: &str) -> Option<&'static str> {
    PROVIDERS
        .iter()
        .find(|(guidy, _)| *guidy == provider_id)
        .map(|(_, models_dev)| *models_dev)
}

/// One model as models.dev describes it (the fields Guidy uses).
#[derive(Serialize, Deserialize, Debug, Clone, PartialEq, Default)]
#[serde(default)]
pub struct RegistryModel {
    pub id: String,
    pub name: String,
    pub reasoning: bool,
    pub tool_call: bool,
    /// Supports JSON-schema constrained output, which summaries rely on.
    pub structured_output: bool,
    /// `YYYY-MM-DD`; newer models sort first.
    pub release_date: Option<String>,
    pub modalities: Modalities,
    pub limit: Limits,
    /// USD per million tokens.
    pub cost: Option<Cost>,
}

#[derive(Serialize, Deserialize, Debug, Clone, PartialEq, Default)]
#[serde(default)]
pub struct Modalities {
    pub input: Vec<String>,
    pub output: Vec<String>,
}

#[derive(Serialize, Deserialize, Debug, Clone, PartialEq, Default)]
#[serde(default)]
pub struct Limits {
    pub context: Option<u64>,
    pub output: Option<u64>,
}

#[derive(Serialize, Deserialize, Debug, Clone, Copy, PartialEq, Default)]
#[serde(default)]
pub struct Cost {
    pub input: Option<f64>,
    pub output: Option<f64>,
}

impl RegistryModel {
    /// Produces text (models.dev lists image, audio and embedding models
    /// too). A model without modalities is assumed to.
    pub fn outputs_text(&self) -> bool {
        self.modalities.output.is_empty() || self.modalities.output.iter().any(|m| m == "text")
    }
}

#[derive(Deserialize)]
struct RawProvider {
    /// Parsed one by one, so a malformed model drops only itself.
    #[serde(default)]
    models: HashMap<String, serde_json::Value>,
}

/// Text models per models.dev provider id.
#[derive(Debug, Clone, Default, PartialEq)]
pub struct Registry {
    providers: HashMap<String, Vec<RegistryModel>>,
    /// When this copy was downloaded (unix seconds); `None` for the
    /// snapshot bundled with the app.
    pub fetched_at: Option<u64>,
}

impl Registry {
    /// Parse models.dev's `api.json` (or the bundled trimmed copy). Only
    /// providers Guidy maps and models that output text are kept. A
    /// malformed provider or model entry is skipped, not fatal.
    pub fn parse(json: &str) -> Result<Self> {
        let raw: HashMap<String, serde_json::Value> =
            serde_json::from_str(json).context("models.dev catalog is not a JSON object")?;
        let wanted = |id: &str| PROVIDERS.iter().any(|(_, models_dev)| *models_dev == id);
        let mut providers = HashMap::new();
        for (id, value) in raw {
            if !wanted(&id) {
                continue;
            }
            let Ok(p) = serde_json::from_value::<RawProvider>(value) else {
                log::warn!("models.dev: skipping malformed provider {id}");
                continue;
            };
            let mut skipped = 0;
            let mut models: Vec<RegistryModel> = p
                .models
                .into_iter()
                .filter_map(|(key, mut value)| {
                    // An explicit null means "not listed", like a missing field.
                    drop_nulls(&mut value);
                    let Ok(mut m) = serde_json::from_value::<RegistryModel>(value) else {
                        skipped += 1;
                        return None;
                    };
                    if m.id.is_empty() {
                        m.id = key;
                    }
                    Some(m)
                })
                .filter(RegistryModel::outputs_text)
                .collect();
            if skipped > 0 {
                log::warn!("models.dev: skipped {skipped} malformed model(s) of {id}");
            }
            sort_newest_first(&mut models);
            providers.insert(id, models);
        }
        if providers.is_empty() {
            return Err(anyhow!("models.dev catalog has none of Guidy's providers"));
        }
        Ok(Self {
            providers,
            fetched_at: None,
        })
    }

    /// The snapshot bundled with the app.
    pub fn bundled() -> Self {
        Self::parse(BUNDLED).expect("bundled LLM registry parses")
    }

    /// A Guidy provider's models (newest first); `None` when models.dev
    /// doesn't describe the provider.
    pub fn models(&self, provider_id: &str) -> Option<&[RegistryModel]> {
        self.providers
            .get(models_dev_provider(provider_id)?)
            .map(Vec::as_slice)
    }

    pub fn find(&self, provider_id: &str, model_id: &str) -> Option<&RegistryModel> {
        let model_id = model_id.trim();
        self.models(provider_id)?.iter().find(|m| m.id == model_id)
    }
}

/// Remove null members from objects, recursively.
fn drop_nulls(value: &mut serde_json::Value) {
    if let serde_json::Value::Object(map) = value {
        map.retain(|_, v| !v.is_null());
        map.values_mut().for_each(drop_nulls);
    }
}

fn sort_newest_first(models: &mut [RegistryModel]) {
    models.sort_by(|a, b| {
        b.release_date
            .cmp(&a.release_date)
            .then_with(|| a.name.cmp(&b.name))
    });
}

/// A model in the picker: the registry's description of it (when known)
/// and whether the provider's live list has it.
#[derive(Serialize, Deserialize, Debug, Clone, PartialEq)]
pub struct ModelEntry {
    pub id: String,
    /// Display name (the id when the registry doesn't know the model).
    pub name: String,
    pub info: Option<RegistryModel>,
}

impl ModelEntry {
    /// Known to support structured output (summaries need it).
    pub fn good_for_summaries(&self) -> bool {
        self.info.as_ref().is_some_and(|m| m.structured_output)
    }
}

/// The picker's list. With a live list (the API key works), its models in
/// registry order, then models the registry doesn't know (alphabetically,
/// without details: new, or not a text model). Without one (no key yet, or
/// the listing failed), the registry's models so a model can still be
/// chosen. A provider models.dev doesn't describe shows the live list as is.
pub fn merge_models(
    registry: Option<&[RegistryModel]>,
    live: Option<&[String]>,
) -> Vec<ModelEntry> {
    let known = |m: &RegistryModel| ModelEntry {
        id: m.id.clone(),
        name: if m.name.is_empty() {
            m.id.clone()
        } else {
            m.name.clone()
        },
        info: Some(m.clone()),
    };
    let unknown = |id: &str| ModelEntry {
        id: id.to_string(),
        name: id.to_string(),
        info: None,
    };
    match (registry, live) {
        (Some(reg), Some(live)) => {
            let mut out: Vec<ModelEntry> = reg
                .iter()
                .filter(|m| live.iter().any(|id| id.trim() == m.id))
                .map(known)
                .collect();
            let mut rest: Vec<&String> = live
                .iter()
                .filter(|id| !reg.iter().any(|m| m.id == id.trim()))
                .collect();
            rest.sort();
            rest.dedup();
            out.extend(rest.into_iter().map(|id| unknown(id)));
            out
        }
        (Some(reg), None) => reg.iter().map(known).collect(),
        (None, Some(live)) => {
            let mut ids: Vec<&String> = live.iter().collect();
            ids.sort();
            ids.dedup();
            ids.into_iter().map(|id| unknown(id)).collect()
        }
        (None, None) => Vec::new(),
    }
}

// -- the shared copy ---------------------------------------------------------

fn cell() -> &'static RwLock<Option<Arc<Registry>>> {
    static C: OnceLock<RwLock<Option<Arc<Registry>>>> = OnceLock::new();
    C.get_or_init(|| RwLock::new(None))
}

/// One refresh at a time.
fn refresh_lock() -> &'static Mutex<()> {
    static L: OnceLock<Mutex<()>> = OnceLock::new();
    L.get_or_init(|| Mutex::new(()))
}

fn cache_path(app: &AppHandle) -> Result<PathBuf> {
    Ok(crate::portable::app_data_dir(app)
        .map_err(|e| anyhow!("app data dir: {e}"))?
        .join(CACHE_FILE))
}

fn unix_now() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0)
}

/// The downloaded copy on disk, stamped with its modification time.
fn read_cache(app: &AppHandle) -> Option<Registry> {
    let path = cache_path(app).ok()?;
    let json = std::fs::read_to_string(&path).ok()?;
    let mut registry = match Registry::parse(&json) {
        Ok(r) => r,
        Err(e) => {
            log::warn!("Ignoring the downloaded LLM registry: {e:#}");
            return None;
        }
    };
    registry.fetched_at = std::fs::metadata(&path)
        .and_then(|m| m.modified())
        .ok()
        .and_then(|t| t.duration_since(UNIX_EPOCH).ok())
        .map(|d| d.as_secs());
    Some(registry)
}

/// The registry in use: the downloaded copy once read, else the bundled
/// one. Doesn't touch the disk; see [`load`].
pub fn current() -> Arc<Registry> {
    if let Some(r) = cell().read().clone() {
        return r;
    }
    let mut slot = cell().write();
    slot.get_or_insert_with(|| Arc::new(Registry::bundled()))
        .clone()
}

/// Read the downloaded copy (if any) into [`current`]. Call once at
/// startup, off the UI thread.
pub fn load(app: &AppHandle) -> Arc<Registry> {
    let registry = Arc::new(read_cache(app).unwrap_or_else(Registry::bundled));
    *cell().write() = Some(registry.clone());
    registry
}

/// Download models.dev's catalog, save it, and make it [`current`].
/// Blocking.
pub fn refresh(app: &AppHandle) -> Result<Arc<Registry>> {
    let _guard = refresh_lock().lock();
    let json = super::block_on(async {
        let client = reqwest::Client::builder()
            .timeout(Duration::from_secs(30))
            .build()?;
        client
            .get(REGISTRY_URL)
            .send()
            .await?
            .error_for_status()?
            .text()
            .await
    })
    .context("couldn't download the model list from models.dev")?;
    let mut registry = Registry::parse(&json)?;
    let path = cache_path(app)?;
    if let Some(dir) = path.parent() {
        std::fs::create_dir_all(dir)?;
    }
    let tmp = path.with_extension("json.tmp");
    std::fs::write(&tmp, &json)?;
    std::fs::rename(&tmp, &path)?;
    registry.fetched_at = Some(unix_now());
    let registry = Arc::new(registry);
    *cell().write() = Some(registry.clone());
    log::info!("LLM registry refreshed from models.dev");
    Ok(registry)
}

/// [`load`], then [`refresh`] on a background thread when the downloaded
/// copy is missing or older than a day. Failures are logged; the bundled
/// copy keeps working offline.
pub fn load_and_refresh_if_stale(app: &AppHandle) {
    let app = app.clone();
    let spawned = std::thread::Builder::new()
        .name("llm-registry".into())
        .spawn(move || {
            let registry = load(&app);
            let stale = registry
                .fetched_at
                .is_none_or(|t| unix_now().saturating_sub(t) > MAX_AGE.as_secs());
            if stale {
                if let Err(e) = refresh(&app) {
                    log::info!("LLM registry not refreshed: {e:#}");
                }
            }
        });
    if let Err(e) = spawned {
        log::warn!("Couldn't start the LLM registry refresh: {e}");
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn model(id: &str, date: &str, structured: bool) -> RegistryModel {
        RegistryModel {
            id: id.into(),
            name: id.to_uppercase(),
            structured_output: structured,
            release_date: Some(date.into()),
            ..Default::default()
        }
    }

    #[test]
    fn bundled_snapshot_covers_the_mapped_providers() {
        let r = Registry::bundled();
        for id in ["anthropic", "openai", "openrouter", "groq"] {
            let models = r.models(id).unwrap_or_default();
            assert!(!models.is_empty(), "{id}");
            assert!(models.iter().all(RegistryModel::outputs_text), "{id}");
        }
        assert!(r.models("custom").is_none());
        assert!(r.fetched_at.is_none());
    }

    #[test]
    fn parse_keeps_text_models_newest_first() {
        let json = r#"{
            "openai": {"id": "openai", "models": {
                "old": {"id": "old", "name": "Old", "release_date": "2024-01-01",
                        "modalities": {"input": ["text"], "output": ["text"]}},
                "new": {"id": "new", "name": "New", "release_date": "2026-01-01",
                        "structured_output": true,
                        "limit": {"context": 1000000, "output": 64000},
                        "cost": {"input": 2, "output": 10}},
                "image": {"id": "image", "name": "Image",
                          "modalities": {"input": ["text"], "output": ["image"]}},
                "nulls": {"id": "nulls", "name": "Nulls", "release_date": "2025-01-01",
                          "reasoning": null, "limit": {"context": null}, "cost": null},
                "broken": {"id": "broken", "limit": {"context": 1.5}}
            }},
            "somebody-else": {"id": "x", "models": {}},
            "groq": "not an object"
        }"#;
        let r = Registry::parse(json).unwrap();
        let ids: Vec<&str> = r
            .models("openai")
            .unwrap()
            .iter()
            .map(|m| m.id.as_str())
            .collect();
        // Nulls are defaults; a malformed model is dropped, not the provider.
        assert_eq!(ids, ["new", "nulls", "old"]);
        let new = r.find("openai", " new ").unwrap();
        assert_eq!(new.limit.context, Some(1_000_000));
        assert_eq!(new.cost.unwrap().output, Some(10.0));
        assert!(r.models("groq").is_none());
        assert!(Registry::parse(r#"{"other": {}}"#).is_err());
        assert!(Registry::parse("[]").is_err());
    }

    #[test]
    fn merge_shows_what_the_key_can_use_described_by_the_registry() {
        let reg = vec![
            model("b", "2026-02-01", true),
            model("a", "2026-01-01", false),
        ];
        let live: Vec<String> = ["whisper-1", "a", "b", "zeta"].map(String::from).to_vec();
        let merged = merge_models(Some(&reg), Some(&live));
        let ids: Vec<&str> = merged.iter().map(|m| m.id.as_str()).collect();
        assert_eq!(ids, ["b", "a", "whisper-1", "zeta"]);
        assert!(merged[0].good_for_summaries());
        assert!(!merged[1].good_for_summaries());
        assert_eq!(merged[0].name, "B");
        assert!(merged[2].info.is_none());
        assert!(!merged[2].good_for_summaries());

        // A model the key can't use isn't offered.
        let merged = merge_models(Some(&reg), Some(&["a".to_string()]));
        assert_eq!(merged.len(), 1);

        // No live list: the registry's models.
        let merged = merge_models(Some(&reg), None);
        assert_eq!(merged.len(), 2);

        // Not in the registry: the live list, sorted.
        let merged = merge_models(None, Some(&live));
        assert_eq!(merged[0].id, "a");
        assert!(merged.iter().all(|m| m.info.is_none()));
        assert!(merge_models(None, None).is_empty());
    }
}
